const AX = { left:"#f0a018", right:"#1a6ff0", top:"#22c55e", bottom:"#e83516" };

// ─── Color math ───────────────────────────────────────────────────────────────
const h2r = h => { const n=parseInt(h.replace("#",""),16); return [(n>>16)&255,(n>>8)&255,n&255]; };
const r2h = (r,g,b) => "#"+[r,g,b].map(v=>Math.round(Math.max(0,Math.min(255,v))).toString(16).padStart(2,"0")).join("");
const ternaryColor = (a,b,c) => {
  const e=2.2,wa=Math.pow(Math.max(0,a),e),wb=Math.pow(Math.max(0,b),e),wc=Math.pow(Math.max(0,c),e),s=wa+wb+wc||.001;
  const [ar,ag,ab]=h2r(POLES[0].color),[br,bg,bb]=h2r(POLES[1].color),[cr,cg,cb]=h2r(POLES[2].color);
  return r2h(ar*(wa/s)+br*(wb/s)+cr*(wc/s),ag*(wa/s)+bg*(wb/s)+cg*(wc/s),ab*(wa/s)+bb*(wb/s)+cb*(wc/s));
};
const axisColor = (x,y) => {
  const tx=x/100-.5,ty=y/100-.5,wL=Math.max(0,-tx),wR=Math.max(0,tx),wT=Math.max(0,-ty),wB=Math.max(0,ty),s=wL+wR+wT+wB||.001;
  const [lr,lg,lb]=h2r(AX.left),[rr,rg,rb]=h2r(AX.right),[tr,tg,tb]=h2r(AX.top),[br2,bg2,bb2]=h2r(AX.bottom);
  return r2h(lr*(wL/s)+rr*(wR/s)+tr*(wT/s)+br2*(wB/s),lg*(wL/s)+rg*(wR/s)+tg*(wT/s)+bg2*(wB/s),lb*(wL/s)+rb*(wR/s)+tb*(wT/s)+bb2*(wB/s));
};

