// ─── Ternary geometry ─────────────────────────────────────────────────────────
const W=340, PAD=46, TRIW=W-2*PAD, TRIH=TRIW*(Math.sqrt(3)/2);
const VA={x:W/2,y:PAD}, VB={x:PAD,y:PAD+TRIH}, VC={x:W-PAD,y:PAD+TRIH};
const VIEW_H=PAD+TRIH+14;
const b2xy=(a,b,c)=>({x:a*VA.x+b*VB.x+c*VC.x,y:a*VA.y+b*VB.y+c*VC.y});
const xy2b=(px,py)=>{
  const d=(VB.y-VC.y)*(VA.x-VC.x)+(VC.x-VB.x)*(VA.y-VC.y);
  const a=((VB.y-VC.y)*(px-VC.x)+(VC.x-VB.x)*(py-VC.y))/d;
  const b=((VC.y-VA.y)*(px-VC.x)+(VA.x-VC.x)*(py-VC.y))/d;
  return {a,b,c:1-a-b};
};
const clampB=(a,b,c)=>{const cl=[Math.max(0,a),Math.max(0,b),Math.max(0,c)],s=cl[0]+cl[1]+cl[2];return s<.001?{a:1/3,b:1/3,c:1/3}:{a:cl[0]/s,b:cl[1]/s,c:cl[2]/s};};
const inTri=(a,b,c)=>a>-0.02&&b>-0.02&&c>-0.02;
const GRID=(()=>{const L=[];for(const t of[1/3,2/3]){L.push([b2xy(t,1-t,0),b2xy(t,0,1-t)]);L.push([b2xy(1-t,t,0),b2xy(0,t,1-t)]);L.push([b2xy(1-t,0,t),b2xy(0,1-t,t)]);}return L;})();
const descTern=(a,b,c)=>{const hi=[a,b,c].indexOf(Math.max(a,b,c)),sec=[a,b,c].map((v,i)=>({v,i})).filter(x=>x.i!==hi).sort((x,y)=>y.v-x.v)[0].i;if(Math.abs(a-b)<.12&&Math.abs(b-c)<.12)return"An even blend — you hold all three perspectives in roughly equal weight.";if(Math.max(a,b,c)>.55)return`Strongly oriented toward ${POLES[hi].label}.`;return`Leaning toward ${POLES[hi].label}, with meaningful weight on ${POLES[sec].label}.`;};

