// ─── Root ─────────────────────────────────────────────────────────────────────
export default function OpinionMaps() {
  const [tab,       setTab]       = useState("ternary");
  const [archetype, setArchetype] = useState(null);
  const arch = ARCHETYPES.find(x=>x.id===archetype);

  return (
    <div style={S.root}>
      <style>{CSS}</style>

      {/* SVG symbol defs — rendered first so <use href="#as-*"> works in any SVG below */}
      <ArchSymbols/>

      {/* Paper grain — fixed overlay matching profile spec */}
      <div style={{position:"fixed",inset:0,pointerEvents:"none",zIndex:0,
        backgroundImage:`url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='g'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23g)' opacity='0.035'/%3E%3C/svg%3E")`
      }}/>

      {/* Nav bar — cream left (logo) → dark right (links), exact from profile spec */}
      <div style={S.nav}>
        <img src={LOGO} alt="Dialecta" style={{height:42,width:"auto",display:"block"}}/>
        <div style={{display:"flex",gap:4}}>
          {["The Forum","Articles","Opinion Maps"].map(l=>(
            <span key={l} style={S.navLink}>{l}</span>
          ))}
        </div>
      </div>

      {/* Article strip */}
      <div style={S.strip}>
        <div style={S.stripMeta}>Society · Psychology · 2026 &nbsp;·&nbsp; <span style={{color:D.gold}}>●</span> 247 readers mapped</div>
        <div style={S.stripTitle}>Social Media, Human Behavior, and the Rewiring of Society</div>
      </div>

      {/* AI banner */}
      <div style={S.aiBanner}>
        <span style={{color:D.amber,flexShrink:0}}>◎</span>
        <div>
          <div style={S.aiHead}>Engine recommends the <strong style={{color:D.amber}}>Ternary Plot</strong></div>
          <div style={S.aiSub}>Three distinct causal frameworks detected — more revealing than a two-axis map.</div>
        </div>
      </div>

      <div style={S.page}>
        {!archetype ? (
          <ArchPicker onSelect={setArchetype}/>
        ) : (
          <>
            {/* Archetype bar */}
            <div style={S.archBar}>
              <div style={{display:"flex",alignItems:"center",gap:8}}>
                <ArchIcon id={arch.id} color={arch.color} size={18}/>
                <span style={{fontSize:"0.8rem",fontWeight:500,color:D.textBody}}>{arch.label}</span>
              </div>
              <button style={S.archChangeBtn} onClick={()=>setArchetype(null)}>Change</button>
            </div>

            {/* Tabs */}
            <div style={S.tabRow}>
              <button style={{...S.tab,...(tab==="ternary"?S.tabAmber:{})}} onClick={()=>setTab("ternary")}>
                Ternary <span style={{...S.chip,...(tab==="ternary"?S.chipAmber:{})}}>◆ Signature</span>
              </button>
              <button style={{...S.tab,...(tab==="axis"?S.tabBlue:{})}} onClick={()=>setTab("axis")}>
                2-Axis <span style={{...S.chip,...(tab==="axis"?S.chipBlue:{})}}>Launch</span>
              </button>
            </div>

            {tab==="ternary"
              ? <TernaryPanel key="tern" archetype={archetype}/>
              : <AxisPanel    key="axis" archetype={archetype}/>}
          </>
        )}
      </div>
    </div>
  );
}

// ─── Archetype picker ─────────────────────────────────────────────────────────
function ArchPicker({onSelect}) {
  const [chosen, setChosen] = useState(null);
  return (
    <div style={S.pickerCard}>
      <div style={S.eyebrow}>Before you map</div>
      <h2 style={S.sectionTitle}>Which archetype fits how you engage?</h2>
      <p style={S.sectionDesc}>Your icon appears as your marker on both maps.</p>
      <div style={S.archGrid}>
        {ARCHETYPES.map(a=>(
          <button key={a.id}
            style={{...S.archCard,...(chosen===a.id?{borderColor:a.color,background:a.color+"10"}:{})}}
            onClick={()=>setChosen(chosen===a.id?null:a.id)}>
            <ArchIcon id={a.id} color={a.color} size={28}/>
            <div style={{...S.archName,color:chosen===a.id?a.color:D.textBody}}>{a.label}</div>
            <div style={S.archDesc}>{a.desc}</div>
          </button>
        ))}
      </div>
      <button style={{...S.btnAccent,opacity:chosen?1:.35,cursor:chosen?"pointer":"not-allowed"}}
        disabled={!chosen} onClick={()=>onSelect(chosen)}>Continue →</button>
    </div>
  );
}

